# Compactly inspect whether local archives have any non-rectangular aligned FASTA among mafft members.
# This is metadata/header/dimension inspection only; no metric is computed.
import zipfile
for p in ['inputs/scogs_animals.zip','inputs/scogs_fungi.zip']:
    total=0; bad=[]; seq_counts=[]
    with zipfile.ZipFile(p) as z:
        for n in z.namelist():
            if not n.endswith('.mafft'): continue
            total+=1; lens=[]; seq=''
            for line in z.read(n).decode('utf-8', 'replace').splitlines():
                if line.startswith('>'):
                    if seq: lens.append(len(seq)); seq=''
                else:
                    seq += line.strip()
            if seq: lens.append(len(seq))
            seq_counts.append(len(lens))
            if len(set(lens))>1: bad.append(n)
    print(p, 'mafft', total, 'nonrectangular', len(bad), 'seq_count_minmax', (min(seq_counts), max(seq_counts)))
PY"

